fn main() {
    // ---- Option represents a value that may or may not exist ----
    // Instead of null, Rust uses Option

    // ---- Creating Options ----
    let some_number = Some(42);
    let some_string = Some(String::from("Hello"));
    let none: Option<i32> = None;

    // ---- Using Option with match ----
    match some_number {
        Some(n) => println!("Number: {}", n),
        None => println!("No number!"),
    }

    // ---- unwrap (use with caution!) ----
    // Unwrap returns the value or panics
    let value = some_number.unwrap();
    println!("Unwrapped: {}", value);

    // ---- unwrap_or (safe unwrap) ----
    let value1 = some_number.unwrap_or(0);
    let value2 = none.unwrap_or(0);
    println!("value1: {}, value2: {}", value1, value2);

    // ---- unwrap_or_else (lazy evaluation) ----
    let value = none.unwrap_or_else(|| 100);
    println!("value: {}", value);

    // ---- if let (concise matching) ----
    if let Some(n) = some_number {
        println!("if let: {}", n);
    }

    // ---- Option methods ----
    // map: transform the value
    let doubled = some_number.map(|n| n * 2);
    println!("Doubled: {:?}", doubled);

    // and_then: chain operations
    let result = some_number
        .and_then(|n| if n > 0 { Some(n * 2) } else { None });
    println!("and_then: {:?}", result);

    // ---- Finding with Option ----
    let numbers = vec![1, 2, 3, 4, 5];
    let first = numbers.iter().find(|&n| n == 3);
    let not_found = numbers.iter().find(|&n| n == 10);

    println!("Found: {:?}", first);
    println!("Not found: {:?}", not_found);

    // ---- Practical example: reading from a map ----
    use std::collections::HashMap;

    let mut scores = HashMap::new();
    scores.insert("Hero", 100);
    scores.insert("Aragorn", 85);

    let hero_score = scores.get("Hero");
    let missing_score = scores.get("Gandalf");

    println!("Hero score: {:?}", hero_score);
    println!("Missing score: {:?}", missing_score);

    // ---- Option in structs ----
    struct Player {
        name: String,
        weapon: Option<String>,
    }

    let player1 = Player {
        name: String::from("Hero"),
        weapon: Some(String::from("Sword")),
    };

    let player2 = Player {
        name: String::from("Gandalf"),
        weapon: None,
    };

    // ---- Using Option in struct ----
    if let Some(weapon) = &player1.weapon {
        println!("{} has a {}", player1.name, weapon);
    } else {
        println!("{} has no weapon", player1.name);
    }

    // ---- unwrap_or with default ----
    let weapon_name = player2.weapon.clone().unwrap_or(String::from("Fists"));
    println!("{} fights with {}", player2.name, weapon_name);
}

fn divide(numerator: f64, denominator: f64) -> Option<f64> {
    if denominator == 0.0 {
        None
    } else {
        Some(numerator / denominator)
    }
}

fn main2() {
    let result1 = divide(10.0, 2.0);
    let result2 = divide(10.0, 0.0);

    println!("10 / 2 = {:?}", result1);
    println!("10 / 0 = {:?}", result2);

    // ---- Chaining Options ----
    let result = divide(10.0, 2.0)
        .map(|n| n * 2.0)
        .and_then(|n| divide(n, 3.0));

    println!("Chained result: {:?}", result);
}

